using System;using System.IO;using System.Linq;using System.Text;using System.Globalization;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Windows.Media.Media3D;
namespace GearLab {
 public sealed class MeshVertex {public double X{get;set;}public double Y{get;set;}public double Z{get;set;}public MeshVertex(){}public MeshVertex(double x,double y,double z){X=x;Y=y;Z=z;}public Point3D Point(){return new Point3D(X,Y,Z);}}
 public sealed class MeshFace {public int A{get;set;}public int B{get;set;}public int C{get;set;}public MeshFace(){}public MeshFace(int a,int b,int c){A=a;B=b;C=c;}public int[] Vertices(){return new[]{A,B,C};}}
 public sealed class MeshDocument {
  public int FormatVersion{get;set;}public string Name{get;set;}public List<MeshVertex> Vertices{get;set;}public List<MeshFace> Faces{get;set;}
  public MeshDocument(){FormatVersion=1;Name="Полигональная модель";Vertices=new List<MeshVertex>();Faces=new List<MeshFace>();}
  public static MeshDocument Cube(){var d=new MeshDocument{Name="Куб 40 мм"};foreach(var p in new[]{new[]{-20,-20,-20},new[]{20,-20,-20},new[]{20,20,-20},new[]{-20,20,-20},new[]{-20,-20,20},new[]{20,-20,20},new[]{20,20,20},new[]{-20,20,20}})d.Vertices.Add(new MeshVertex(p[0],p[1],p[2]));foreach(var f in new[]{new[]{0,2,1},new[]{0,3,2},new[]{4,5,6},new[]{4,6,7},new[]{0,1,5},new[]{0,5,4},new[]{1,2,6},new[]{1,6,5},new[]{2,3,7},new[]{2,7,6},new[]{3,0,4},new[]{3,4,7}})d.Faces.Add(new MeshFace(f[0],f[1],f[2]));return d;}
  public List<string> Validate(bool solid){var e=new List<string>();if(FormatVersion!=1||Vertices==null||Faces==null){e.Add("Неверный формат сетки.");return e;}if(Vertices.Count<3||Vertices.Count>200000||Faces.Count<1||Faces.Count>200000){e.Add("Допустимо до 200000 вершин и треугольников.");return e;}if(Vertices.Any(v=>v==null||!MechanismCad.Finite(v.X)||!MechanismCad.Finite(v.Y)||!MechanismCad.Finite(v.Z)||Math.Abs(v.X)>10000||Math.Abs(v.Y)>10000||Math.Abs(v.Z)>10000)){e.Add("Неверные координаты сетки.");return e;}var edges=new Dictionary<string,int[]>();foreach(var f in Faces){if(f==null||f.A<0||f.B<0||f.C<0||f.A>=Vertices.Count||f.B>=Vertices.Count||f.C>=Vertices.Count){e.Add("Неверные индексы треугольника.");return e;}var a=Vertices[f.A].Point();var b=Vertices[f.B].Point();var c=Vertices[f.C].Point();if(Vector3D.CrossProduct(b-a,c-a).LengthSquared<1e-14){e.Add("Вырожденный треугольник.");return e;}var v=f.Vertices();for(int i=0;i<3;i++){int x=v[i],y=v[(i+1)%3];string key=Math.Min(x,y)+":"+Math.Max(x,y);int[] state;if(!edges.TryGetValue(key,out state)){state=new int[2];edges[key]=state;}state[0]++;state[1]+=x<y?1:-1;}}if(solid&&edges.Values.Any(s=>s[0]!=2||s[1]!=0))e.Add("Сетка не замкнута или рёбра/нормали несогласованы.");if(solid&&e.Count==0&&Volume()<=1e-7)e.Add("Неположительный ориентированный объём.");return e;}
  public double Volume(){double sum=0;foreach(var f in Faces){var a=Vertices[f.A].Point();var b=Vertices[f.B].Point();var c=Vertices[f.C].Point();sum+=Vector3D.DotProduct(RobotMath.Vector(a),Vector3D.CrossProduct(RobotMath.Vector(b),RobotMath.Vector(c)))/6;}return sum;}
  public SceneMesh ToScene(){var p=new List<Point3D>();var n=new List<Vector3D>();var indices=new List<int>();foreach(var f in Faces){var a=Vertices[f.A].Point();var b=Vertices[f.B].Point();var c=Vertices[f.C].Point();var normal=Vector3D.CrossProduct(b-a,c-a);normal.Normalize();int start=p.Count;p.AddRange(new[]{a,b,c});n.AddRange(new[]{normal,normal,normal});indices.AddRange(new[]{start,start+1,start+2});}return new SceneMesh{Points=p.ToArray(),Normals=n.ToArray(),Indices=indices.ToArray()};}
  public static MeshDocument FromScene(SceneMesh mesh,string name){var d=new MeshDocument{Name=name};var keys=new Dictionary<string,int>();Func<Point3D,int> vertex=p=>{string key=Math.Round(p.X,6).ToString("R",CultureInfo.InvariantCulture)+","+Math.Round(p.Y,6).ToString("R",CultureInfo.InvariantCulture)+","+Math.Round(p.Z,6).ToString("R",CultureInfo.InvariantCulture);int index;if(!keys.TryGetValue(key,out index)){index=d.Vertices.Count;keys[key]=index;d.Vertices.Add(new MeshVertex(p.X,p.Y,p.Z));}return index;};for(int i=0;i<mesh.Indices.Length;i+=3){int a=vertex(mesh.Points[mesh.Indices[i]]),b=vertex(mesh.Points[mesh.Indices[i+1]]),c=vertex(mesh.Points[mesh.Indices[i+2]]);if(a!=b&&b!=c&&a!=c)d.Faces.Add(new MeshFace(a,b,c));}if(d.Volume()<0)foreach(var f in d.Faces){int b=f.B;f.B=f.C;f.C=b;}return d;}
  public HashSet<int> Coplanar(int selected){var set=new HashSet<int>();if(selected<0||selected>=Faces.Count)return set;var first=Faces[selected];var origin=Vertices[first.A].Point();var normal=Vector3D.CrossProduct(Vertices[first.B].Point()-origin,Vertices[first.C].Point()-origin);normal.Normalize();var candidates=new HashSet<int>();for(int i=0;i<Faces.Count;i++){var f=Faces[i];var a=Vertices[f.A].Point();var n=Vector3D.CrossProduct(Vertices[f.B].Point()-a,Vertices[f.C].Point()-a);n.Normalize();if(Vector3D.DotProduct(n,normal)>.999999&&Math.Abs(Vector3D.DotProduct(a-origin,normal))<1e-5)candidates.Add(i);}set.Add(selected);bool changed=true;while(changed){changed=false;var boundary=new HashSet<string>();foreach(int index in set){var v=Faces[index].Vertices();for(int i=0;i<3;i++)boundary.Add(Math.Min(v[i],v[(i+1)%3])+":"+Math.Max(v[i],v[(i+1)%3]));}foreach(int index in candidates.ToArray())if(!set.Contains(index)){var v=Faces[index].Vertices();if(Enumerable.Range(0,3).Any(i=>boundary.Contains(Math.Min(v[i],v[(i+1)%3])+":"+Math.Max(v[i],v[(i+1)%3])))){set.Add(index);changed=true;}}}return set;}
  public void Extrude(int selected,double distance){if(!MechanismCad.Finite(distance)||Math.Abs(distance)<.01||Math.Abs(distance)>1000)throw new Exception("Высота выдавливания от 0,01 до 1000 мм по модулю.");var group=Coplanar(selected);if(group.Count==0)throw new Exception("Выберите грань.");var face=Faces[selected];var normal=Vector3D.CrossProduct(Vertices[face.B].Point()-Vertices[face.A].Point(),Vertices[face.C].Point()-Vertices[face.A].Point());normal.Normalize();var copied=new Dictionary<int,int>();foreach(int index in group.SelectMany(i=>Faces[i].Vertices()).Distinct()){var p=Vertices[index].Point()+normal*distance;copied[index]=Vertices.Count;Vertices.Add(new MeshVertex(p.X,p.Y,p.Z));}var edges=new Dictionary<string,Tuple<int,int,int>>();foreach(int index in group){var v=Faces[index].Vertices();for(int i=0;i<3;i++){int a=v[i],b=v[(i+1)%3];string key=Math.Min(a,b)+":"+Math.Max(a,b);Tuple<int,int,int> old;edges[key]=edges.TryGetValue(key,out old)?Tuple.Create(old.Item1,old.Item2,old.Item3+1):Tuple.Create(a,b,1);}}var added=group.Select(i=>new MeshFace(copied[Faces[i].A],copied[Faces[i].B],copied[Faces[i].C])).ToList();foreach(var e in edges.Values.Where(e=>e.Item3==1)){int a=e.Item1,b=e.Item2;added.Add(new MeshFace(a,b,copied[b]));added.Add(new MeshFace(a,copied[b],copied[a]));}Faces=Faces.Where((f,i)=>!group.Contains(i)).Concat(added).ToList();}
  public void Subdivide(){if(Faces.Count>45000)throw new Exception("Слишком много граней для подразделения.");var edges=new Dictionary<string,int>();Func<int,int,int> mid=(a,b)=>{string key=Math.Min(a,b)+":"+Math.Max(a,b);int index;if(!edges.TryGetValue(key,out index)){var x=Vertices[a];var y=Vertices[b];index=Vertices.Count;Vertices.Add(new MeshVertex((x.X+y.X)/2,(x.Y+y.Y)/2,(x.Z+y.Z)/2));edges[key]=index;}return index;};var output=new List<MeshFace>();foreach(var f in Faces){int a=mid(f.A,f.B),b=mid(f.B,f.C),c=mid(f.C,f.A);output.Add(new MeshFace(f.A,a,c));output.Add(new MeshFace(a,f.B,b));output.Add(new MeshFace(c,b,f.C));output.Add(new MeshFace(a,b,c));}Faces=output;}
  static JavaScriptSerializer Serializer(){return new JavaScriptSerializer{MaxJsonLength=32*1024*1024,RecursionLimit=32};}public string Serialize(){return Serializer().Serialize(this);}public MeshDocument Clone(){return Serializer().Deserialize<MeshDocument>(Serialize());}public static MeshDocument Parse(string text){if(text==null||text.Length>32*1024*1024)throw new Exception("Слишком большой файл сетки.");var d=Serializer().Deserialize<MeshDocument>(text);if(d==null)throw new Exception("Неверная сетка.");var e=d.Validate(false);if(e.Count>0)throw new Exception(e[0]);return d;}
  public void Save(string path){ReleaseSupport.WriteText(path,Serialize(),new UTF8Encoding(true));}
  public void Stl(string path){var e=Validate(true);if(e.Count>0)throw new Exception(string.Join("; ",e));using(var stream=File.Create(path))using(var w=new BinaryWriter(stream)){var head=new byte[80];Encoding.ASCII.GetBytes("GearLab polygon mesh; millimeters").CopyTo(head,0);w.Write(head);w.Write((uint)Faces.Count);foreach(var f in Faces){var a=Vertices[f.A].Point();var b=Vertices[f.B].Point();var c=Vertices[f.C].Point();var n=Vector3D.CrossProduct(b-a,c-a);n.Normalize();w.Write((float)n.X);w.Write((float)n.Y);w.Write((float)n.Z);foreach(var p in new[]{a,b,c}){w.Write((float)p.X);w.Write((float)p.Y);w.Write((float)p.Z);}w.Write((ushort)0);}}}
  public void Obj(string path){var text=new StringBuilder("# GearLab; units mm\n");foreach(var v in Vertices)text.AppendLine("v "+Engine.N(v.X)+" "+Engine.N(v.Y)+" "+Engine.N(v.Z));foreach(var f in Faces)text.AppendLine("f "+(f.A+1)+" "+(f.B+1)+" "+(f.C+1));ReleaseSupport.WriteText(path,text.ToString(),Encoding.UTF8);}
  public static MeshDocument Import(string path){if(new FileInfo(path).Length>32*1024*1024)throw new Exception("Максимум 32 МБ на сетку.");if(path.EndsWith(".json",StringComparison.OrdinalIgnoreCase))return Parse(File.ReadAllText(path));var positions=new List<Point3D>();var faces=new List<int>();if(path.EndsWith(".obj",StringComparison.OrdinalIgnoreCase)){foreach(string line in File.ReadLines(path)){var a=line.Trim().Split((char[])null,StringSplitOptions.RemoveEmptyEntries);if(a.Length==0)continue;if(a[0]=="v"&&a.Length>=4)positions.Add(new Point3D(double.Parse(a[1],CultureInfo.InvariantCulture),double.Parse(a[2],CultureInfo.InvariantCulture),double.Parse(a[3],CultureInfo.InvariantCulture)));else if(a[0]=="f"&&a.Length>=4){if(a.Length>5)throw new Exception("OBJ: сначала триангулируйте многоугольники с более чем четырьмя вершинами.");var ids=a.Skip(1).Select(s=>int.Parse(s.Split('/')[0],CultureInfo.InvariantCulture)).Select(i=>i>0?i-1:positions.Count+i).ToArray();for(int i=1;i<ids.Length-1;i++)faces.AddRange(new[]{ids[0],ids[i],ids[i+1]});}}}else{using(var stream=File.OpenRead(path))using(var reader=new BinaryReader(stream)){bool binary=false;if(stream.Length>=84){stream.Position=80;uint count=reader.ReadUInt32();binary=count<=200000&&stream.Length==84L+50L*count;if(binary){for(int i=0;i<count;i++){reader.ReadBytes(12);for(int j=0;j<3;j++){faces.Add(positions.Count);positions.Add(new Point3D(reader.ReadSingle(),reader.ReadSingle(),reader.ReadSingle()));}reader.ReadUInt16();}}}if(!binary){foreach(string line in File.ReadLines(path)){var a=line.Trim().Split((char[])null,StringSplitOptions.RemoveEmptyEntries);if(a.Length==4&&a[0]=="vertex"){faces.Add(positions.Count);positions.Add(new Point3D(double.Parse(a[1],CultureInfo.InvariantCulture),double.Parse(a[2],CultureInfo.InvariantCulture),double.Parse(a[3],CultureInfo.InvariantCulture)));}}if(faces.Count%3!=0)throw new Exception("Неполный треугольник STL.");}}}if(positions.Count==0||faces.Any(i=>i<0||i>=positions.Count))throw new Exception("Неверная сетка.");var d=FromScene(new SceneMesh{Points=positions.ToArray(),Indices=faces.ToArray()},Path.GetFileNameWithoutExtension(path));var errors=d.Validate(false);if(errors.Count>0)throw new Exception(errors[0]);return d;}
 }
}
